
CREATE TABLE user_account(id uuid PRIMARY KEY,campus_subject varchar(128) UNIQUE,nickname varchar(40) NOT NULL,avatar_url varchar(512),department varchar(80),verified boolean NOT NULL DEFAULT false,status varchar(16) NOT NULL DEFAULT 'NORMAL' CHECK(status IN ('NORMAL','DISABLED','DELETED')),role varchar(16) NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')),contact_ciphertext text,demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE privacy_setting(user_id uuid PRIMARY KEY REFERENCES user_account(id),contact_visibility varchar(16) NOT NULL DEFAULT 'HIDDEN' CHECK(contact_visibility IN ('HIDDEN','GROUP')),location_visibility varchar(16) NOT NULL DEFAULT 'HIDDEN' CHECK(location_visibility IN ('HIDDEN','GROUP')));
CREATE TABLE activity(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES user_account(id),type varchar(24) NOT NULL CHECK(type IN ('STUDY','SPORT','TRAVEL','MEAL','OTHER')),title varchar(80) NOT NULL,description varchar(2000) NOT NULL DEFAULT '',campus varchar(40) NOT NULL,tags jsonb NOT NULL DEFAULT '[]',start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,deadline timestamptz NOT NULL,confirmation_deadline timestamptz NOT NULL,ended_at timestamptz,capacity integer NOT NULL CHECK(capacity>=1),status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','ENDED','CANCELLED','ARCHIVED')),terminal_state varchar(20) CHECK(terminal_state IN ('ENDED','CANCELLED')),version bigint NOT NULL DEFAULT 0,visibility varchar(16) NOT NULL DEFAULT 'VISIBLE' CHECK(visibility IN ('VISIBLE','HIDDEN')),public_location varchar(120) NOT NULL,exact_location_ciphertext text,public_lat numeric(9,6),public_lon numeric(9,6),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(start_at<end_at AND deadline<=confirmation_deadline AND confirmation_deadline<=start_at),CHECK((public_lat IS NULL)=(public_lon IS NULL)),CHECK(public_lat BETWEEN -90 AND 90 AND public_lon BETWEEN -180 AND 180));
CREATE INDEX activity_discovery ON activity(status,start_at,id);
CREATE INDEX activity_type ON activity(type,campus,start_at);
CREATE TABLE application(id uuid PRIMARY KEY,activity_id uuid NOT NULL REFERENCES activity(id),user_id uuid NOT NULL REFERENCES user_account(id),round integer NOT NULL DEFAULT 1 CHECK(round>=1),version bigint NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','WITHDRAWN','EXPIRED','CANCELLED')),note varchar(300) NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(activity_id,user_id));
CREATE INDEX application_pending ON application(activity_id,status);
CREATE TABLE participation(id uuid PRIMARY KEY,activity_id uuid NOT NULL REFERENCES activity(id),user_id uuid NOT NULL REFERENCES user_account(id),role varchar(12) NOT NULL CHECK(role IN ('OWNER','MEMBER')),status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','LEFT','REMOVED')),confirmation varchar(20) NOT NULL DEFAULT 'UNCONFIRMED' CHECK(confirmation IN ('UNCONFIRMED','CONFIRMED','LEAVE')),version bigint NOT NULL DEFAULT 0,joined_at timestamptz NOT NULL DEFAULT now(),left_at timestamptz,checkin_at timestamptz,checkin_status varchar(16) NOT NULL DEFAULT 'NOT_REPORTED' CHECK(checkin_status IN ('NOT_REPORTED','SELF_REPORTED')),UNIQUE(activity_id,user_id),CHECK(status<>'ACTIVE' OR left_at IS NULL));
CREATE INDEX participation_user ON participation(user_id,status);
CREATE INDEX participation_activity ON participation(activity_id,status);
CREATE TABLE temporary_group(id uuid PRIMARY KEY,activity_id uuid NOT NULL UNIQUE REFERENCES activity(id),access_mode varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(access_mode IN ('ACTIVE','READ_ONLY','BLOCKED')),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE completion_snapshot(activity_id uuid NOT NULL REFERENCES activity(id),user_id uuid NOT NULL REFERENCES user_account(id),role varchar(12) NOT NULL,ended_at timestamptz NOT NULL,PRIMARY KEY(activity_id,user_id));
CREATE TABLE application_history(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES application(id),round int NOT NULL,from_status varchar(20),to_status varchar(20) NOT NULL,actor_id uuid NOT NULL REFERENCES user_account(id),reason varchar(500),request_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX application_history_round ON application_history(application_id,round);
CREATE TABLE activity_change(id uuid PRIMARY KEY,activity_id uuid NOT NULL REFERENCES activity(id),old_version bigint NOT NULL,new_version bigint NOT NULL,old_values jsonb NOT NULL,new_values jsonb NOT NULL,summary varchar(500) NOT NULL,actor_id uuid NOT NULL REFERENCES user_account(id),request_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE message(id uuid PRIMARY KEY,group_id uuid NOT NULL REFERENCES temporary_group(id),sender_id uuid NOT NULL REFERENCES user_account(id),client_message_id uuid NOT NULL,body varchar(1000) NOT NULL CHECK(length(trim(body))>0),request_hash char(64) NOT NULL,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,sender_id,client_message_id));
CREATE INDEX message_page ON message(group_id,created_at,id);
CREATE TABLE group_pin(group_id uuid PRIMARY KEY REFERENCES temporary_group(id),body varchar(2000) NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 0,editor_id uuid NOT NULL REFERENCES user_account(id));
CREATE TABLE feedback(id uuid PRIMARY KEY,activity_id uuid NOT NULL,user_id uuid NOT NULL,completion varchar(16) NOT NULL CHECK(completion IN ('COMPLETED','PARTIAL','NOT_COMPLETED')),reason varchar(500),experience smallint NOT NULL CHECK(experience BETWEEN 1 AND 5),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(activity_id,user_id),FOREIGN KEY(activity_id,user_id) REFERENCES completion_snapshot(activity_id,user_id),CHECK(completion='COMPLETED' OR length(trim(reason))>0));
CREATE TABLE peer_rating(id uuid PRIMARY KEY,feedback_id uuid NOT NULL REFERENCES feedback(id),target_user_id uuid NOT NULL REFERENCES user_account(id),score smallint NOT NULL CHECK(score BETWEEN 1 AND 5),comment varchar(300),UNIQUE(feedback_id,target_user_id));
CREATE TABLE notification(id uuid PRIMARY KEY,event_id uuid NOT NULL,recipient_id uuid NOT NULL REFERENCES user_account(id),type varchar(40) NOT NULL,payload jsonb NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,recipient_id,type));
CREATE INDEX notification_page ON notification(recipient_id,created_at DESC,id);
CREATE TABLE delivery_task(id uuid PRIMARY KEY,event_id uuid NOT NULL,recipient_id uuid NOT NULL REFERENCES user_account(id),channel varchar(20) NOT NULL DEFAULT 'MOCK',status varchar(20) NOT NULL DEFAULT 'READY' CHECK(status IN ('READY','RUNNING','RETRY','FAILED','ACCEPTED','OBSOLETE','QUARANTINED')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 30),next_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,schema_version integer NOT NULL DEFAULT 1,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,recipient_id,channel),CHECK(status<>'RUNNING' OR (lease_until IS NOT NULL AND lease_token IS NOT NULL)));
CREATE INDEX delivery_due ON delivery_task(status,next_at);
CREATE TABLE delivery_attempt(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES delivery_task(id),attempt_no int NOT NULL CHECK(attempt_no>=1),result varchar(20) NOT NULL,latency_ms integer,error_code varchar(64),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(task_id,attempt_no));
CREATE TABLE idempotency_record(actor_id uuid NOT NULL REFERENCES user_account(id),operation varchar(128) NOT NULL,key uuid NOT NULL,request_hash char(64) NOT NULL,response_json jsonb,http_status smallint,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,operation,key));
CREATE TABLE report(id uuid PRIMARY KEY,reporter_id uuid NOT NULL REFERENCES user_account(id),target_type varchar(16) NOT NULL CHECK(target_type IN ('ACTIVITY','USER','MESSAGE')),target_id uuid NOT NULL,status varchar(24) NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','ACCEPTED','PROCESSING','RESOLVED','APPEAL_PENDING','APPEAL_RESOLVED')),reason varchar(1000) NOT NULL,evidence varchar(2000) NOT NULL DEFAULT '',accepted_at timestamptz,decision jsonb,version bigint NOT NULL DEFAULT 0,disposition_id uuid UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX report_sla ON report(status,created_at);
CREATE TABLE appeal(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES report(id),appellant_id uuid NOT NULL REFERENCES user_account(id),reason varchar(1000) NOT NULL,evidence varchar(2000) NOT NULL DEFAULT '',status varchar(24) NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','UPHELD','REVOKED')),result varchar(1000),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(report_id,appellant_id));
CREATE TABLE audit_log(id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES user_account(id),action varchar(40) NOT NULL,resource_id uuid NOT NULL,reason text NOT NULL CHECK(length(trim(reason))>0),request_id varchar(64) NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_resource ON audit_log(resource_id,created_at);
CREATE TABLE erasure_log(user_id uuid PRIMARY KEY REFERENCES user_account(id),erased_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE SPRING_SESSION(PRIMARY_ID CHAR(36) NOT NULL,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100),CONSTRAINT SPRING_SESSION_PK PRIMARY KEY(PRIMARY_ID));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BYTEA NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
CREATE FUNCTION prevent_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only history'; END; $$;
CREATE TRIGGER immutable_snapshot BEFORE UPDATE OR DELETE ON completion_snapshot FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_application_history BEFORE UPDATE OR DELETE ON application_history FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
